const C = {"P":{"origin":[300,239.78085307871007],"scale":1.1782358189133506,"azimuth":45,"elevation":30},"TL":{"ZYM":[0.3,2.6],"MAC":[1.6,3.6],"INJB":[3.8,5.4],"INJF":[5.6,7.2],"SPREAD":1.2,"SHEATH":[7.6,10.6],"END":13},"STOP":{"zym":50,"back":-52,"front":52,"park":-96},"N":7,"SYRZ":42,"FZ":16};
