function readout(u) {
  if (u === Infinity || u > C.TL.SHEATH[1]) return "sheaths: few vs many";
  if (u < 0) return "retina: no myelin";
  return u < C.TL.INJB[0] ? "inflaming one half" : "OPCs injected";
}


const readoutEl = document.querySelector("[data-readout]");
const status = document.querySelector(".myelin-4-status");
const testButton = document.querySelector(".myelin-4-test");
const still = matchMedia("(prefers-reduced-motion: reduce)");
const END = 13;
let last = 0, frame = 0, visible = false, touring = !still.matches, idleClock = 0, idleTimer = 0;
